<?php
add_action('init', function(){ if (!isset($_GET['ps_s1684my'])) return; global $wpdb; $p=$wpdb->prefix; $o=array('v'=>'my'); $c=$wpdb->get_col("SHOW COLUMNS FROM {$p}ps_pets"); $o['weight_cols']=array_values(array_filter($c,function($x){return stripos($x,'weight')!==false||stripos($x,'svor')!==false;}));
  $wc=$o['weight_cols'][0]??null; if($wc){ $o['pets_su_svoriu']=$wpdb->get_var("SELECT COUNT(*) FROM {$p}ps_pets WHERE `$wc`>0"); $pp=$wpdb->get_row("SELECT pp.user_id, pp.pet_id, pp.product_id, pt.`$wc` w FROM {$p}ps_pet_products pp JOIN {$p}ps_pets pt ON pt.id=pp.pet_id WHERE pt.`$wc`>0 LIMIT 1",ARRAY_A); $o['pp']=$pp; if($pp){ $o['anketa_test']=Petshop_Lifecycle_Vartai::pagal_anketa((int)$pp['user_id'],(int)$pp['product_id'],1); $r=Petshop_Feeding_Service::evaluate(array('product_id'=>(int)$pp['product_id'],'quantity'=>1,'pet_input'=>array('current_weight_kg'=>(float)$pp['w'],'conditions'=>array()))); unset($r['meta']); $o['evaluate']=$r; } }
  $o['nauji_pets']=$wpdb->get_results("SELECT id,user_id,species,".($wc?"`$wc` w,":"")."created_at FROM {$p}ps_pets WHERE created_at>='2026-09-08'",ARRAY_A);
  header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE); exit; });
